import json,numpy as np
from scipy.optimize import least_squares
s=json.load(open('/app/output/spec.json'));names=s['proprio']['joints'];p=np.array(s['proprio']['position_m']);axis=np.array(s['proprio']['axis']);links=s['links'];
def rot(a,t):
 a=a/np.linalg.norm(a);A=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]]);return np.eye(3)+np.sin(t)*A+(1-np.cos(t))*(A@A)
def hand(side,q):
 out=np.array(links['com_m'][16 if side=='left' else 21]);idx=[names.index(side+'_'+x) for x in ['shoulder_pitch','shoulder_roll','shoulder_yaw','elbow']]
 for i,t in reversed(list(zip(idx,q))):out=p[i]+rot(axis[i],t)@(out-p[i])
 return out
if __name__=='__main__':
 q0=np.array([-1.62,-.06,-.5,.72]);lims=np.array([s['action_types']['joint_position']['range_rad'][names.index('right_'+x)] for x in ['shoulder_pitch','shoulder_roll','shoulder_yaw','elbow']]);
 for target in [(0,-.15,.55),(.1,-.15,.5),(.3,-.1,.6),(.7,-.1,.85),(.7,-.25,.85)]:
  tar=np.array(target);fit=least_squares(lambda q:np.r_[5*(hand('right',q)-tar),.15*(q-q0)],q0,bounds=(lims[:,0],lims[:,1]));print(target,fit.x,hand('right',fit.x))
